<!-- 条件规则与客户专属价：普通表单创建单条件联动，完整JSON编辑器保留多条件与多结果能力。保存均由服务端检查依赖图和报价。 -->
<script setup lang="ts">
import { KimaCheckbox, KimaNumberField } from '@kernel4632/kima';
import type { BillingPeriod } from '~/types/api';
type Option = { key:string; name:string; kind:string; minimum:number; maximum:number; choices:{value:string;label:string}[] };
type Scalar = string|number|boolean;
type Condition = {key:string;operator:string;value:Scalar|Scalar[]};
type Effect = {key:string;allowedValues?:Scalar[];minimum?:number;maximum?:number;hidden?:boolean;required?:boolean;defaultValue?:Scalar};
type Rule = {id?:string;name:string;priority:number;active:boolean;match:'all'|'any';conditions:Condition[];effects:Effect[]};
type CustomPrice = {id:string;userId:string;email:string|null;name:string;period:BillingPeriod;currency:string;currencyDecimals?:number;configuration:Record<string,Scalar>|null;priceCents:string;setupCents:string;active:boolean;expiresAt:string|null};
const props = defineProps<{productId:string;options:Option[];periods:{period:BillingPeriod;label:string}[];currency:string;currencyDecimals?:number}>();
const api=useApi();
const {data:rules,refresh:refreshRules,error,pending}=await useAsyncData(`catalogue-rules-${props.productId}`,()=>api<Rule[]>(`/admin/catalogue/products/${props.productId}/rules`));
const {data:prices,refresh:refreshPrices}=await useAsyncData(`catalogue-prices-${props.productId}`,()=>api<CustomPrice[]>(`/admin/catalogue/products/${props.productId}/prices`));
const busy=ref(false),failure=ref(''),success=ref(''),advanced=ref(false),json=ref('[]');
watch(rules,value=>{json.value=JSON.stringify(value??[],null,2);},{immediate:true});
const form=reactive({name:'',when:'$period',operator:'eq',value:'month',target:'',result:'allow',allowed:'',minimum:0,maximum:100,priority:0});
const source=computed(()=>props.options.find(item=>item.key===form.when)),target=computed(()=>props.options.find(item=>item.key===form.target));
const fields=computed(()=>[{value:'$period',label:'计费周期'},...props.options.map(item=>({value:item.key,label:item.name}))]);
const values=computed(()=>form.when==='$period'?props.periods.map(item=>({value:item.period,label:item.label})):source.value?.kind==='boolean'?[{value:'true',label:'是'},{value:'false',label:'否'}]:source.value?.choices.map(item=>({value:item.value,label:item.label}))??[]);
watch(()=>form.when,()=>{form.value=values.value[0]?.value||'0';});
watch(()=>form.target,()=>{form.allowed=target.value?.kind==='boolean'?'true':target.value?.choices[0]?.value||'';form.minimum=target.value?.minimum||0;form.maximum=target.value?.maximum||100;form.result=target.value?.kind==='quantity'?'range':'allow';});
function scalar(text:string,option?:Option):Scalar {if(option?.kind==='boolean'){if(!['true','false'].includes(text))throw new Error('开关条件请填写true或false');return text==='true';}if(option?.kind==='quantity'){if(!/^\d+$/.test(text))throw new Error('数量条件需要整数');return Number(text);}return text;}
async function saveRules(next:Rule[]){busy.value=true;failure.value='';success.value='';try{await api(`/admin/catalogue/products/${props.productId}/rules`,{method:'PUT',body:{rules:next}});await refreshRules();success.value='联动规则已保存，购买和变更都会重新核对。';}catch(reason){failure.value=apiMessage(reason);}finally{busy.value=false;}}
async function addRule(){try{if(!form.name.trim()||!form.target)throw new Error('填写规则名称并选择结果配置。');const when:Condition={key:form.when,operator:form.operator,value:['in','not_in'].includes(form.operator)?form.value.split(',').map(value=>scalar(value.trim(),source.value)):scalar(form.value,source.value)};let effect:Effect={key:form.target};if(form.result==='hide')effect.hidden=true;else if(form.result==='require')effect.required=true;else if(form.result==='range'){effect.minimum=form.minimum;effect.maximum=form.maximum;}else effect.allowedValues=form.allowed.split(',').map(value=>scalar(value.trim(),target.value));await saveRules([...(rules.value||[]),{name:form.name.trim(),priority:form.priority,active:true,match:'all',conditions:[when],effects:[effect]}]);}catch(reason){failure.value=reason instanceof Error?reason.message:apiMessage(reason);}}
async function saveJSON(){try{const next:unknown=JSON.parse(json.value);if(!Array.isArray(next))throw new Error('规则需要是JSON数组。');await saveRules(next);}catch(reason){failure.value=reason instanceof Error?reason.message:apiMessage(reason);}}
const search=ref(''),clients=ref<{id:string;name:string;email:string|null}[]>([]);
const price=reactive({userId:'',period:'month' as BillingPeriod,price:'',setup:'0.00',configuration:'',expiresAt:'',active:true});
async function findClients(){busy.value=true;failure.value='';try{clients.value=(await api<{items:typeof clients.value}>(`/admin/clients?limit=50&keyword=${encodeURIComponent(search.value)}`)).items;}catch(reason){failure.value=apiMessage(reason);}finally{busy.value=false;}}
async function savePrice(existing?:CustomPrice){busy.value=true;failure.value='';success.value='';try{const configuration=existing?existing.configuration:price.configuration.trim()?JSON.parse(price.configuration):null;await api(`/admin/catalogue/products/${props.productId}/prices`,{method:'POST',body:existing?{userId:existing.userId,period:existing.period,currency:existing.currency,configuration,priceCents:existing.priceCents,setupCents:existing.setupCents,active:!existing.active,expiresAt:existing.expiresAt}:{userId:price.userId,period:price.period,currency:props.currency,configuration,priceCents:toCents(price.price,true,props.currency,props.currencyDecimals),setupCents:toCents(price.setup,true,props.currency,props.currencyDecimals),active:price.active,expiresAt:price.expiresAt?new Date(price.expiresAt).toISOString():null}});await refreshPrices();success.value='客户专属价已保存，历史成交价格保持原快照。';}catch(reason){failure.value=reason instanceof Error?reason.message:apiMessage(reason);}finally{busy.value=false;}}
</script>
<template>
  <KimaCard class="p-5 sm:p-7 grid gap-6">
    <div><h2 class="text-xl font-semibold">条件与链式配置</h2><p class="form-hint mt-2">先保存上面的资源配置，再建立联动。规则按优先级执行；同一配置的可选范围取交集，循环引用会被拒绝。</p></div>
    <RequestState :pending="pending" :error="error" @retry="refreshRules" />
    <KimaAlert v-if="failure" variant="danger">{{ failure }}</KimaAlert><KimaAlert v-if="success" variant="success">{{ success }}</KimaAlert>
    <div v-for="(rule,index) in rules||[]" :key="rule.id||index" class="border rounded-2xl p-4 grid gap-3" style="border-color:var(--kima-color-outline-variant)">
      <div class="flex flex-wrap items-center justify-between gap-3"><h3 class="font-semibold">{{ rule.name }}</h3><KimaChip>{{ rule.active?'生效':'停用' }} · 优先级 {{ rule.priority }}</KimaChip></div>
      <p class="form-hint">{{ rule.conditions.length }} 个条件，{{ rule.match==='any'?'任一满足':'全部满足' }}时约束 {{ rule.effects.map(item=>options.find(option=>option.key===item.key)?.name||item.key).join('、') }}。</p>
      <div class="flex flex-wrap gap-3"><KimaButton variant="tonal" :disabled="busy" @click="saveRules((rules||[]).map((item,i)=>i===index?{...item,active:!item.active}:item))">{{ rule.active?'停用':'启用' }}</KimaButton><KimaButton variant="text" :disabled="busy" @click="saveRules((rules||[]).filter((_,i)=>i!==index))">删除规则</KimaButton></div>
    </div>
    <form class="grid gap-4" @submit.prevent="addRule">
      <h3 class="font-semibold">新增联动</h3>
      <div class="grid gap-4 sm:grid-cols-2"><label class="grid gap-2">规则名称<KimaTextField v-model="form.name" label="规则名称" required maxlength="100" /></label><div class="grid min-w-0 gap-2"><span class="form-label">规则优先级</span><KimaNumberField v-model="form.priority" label="规则优先级" class="w-full min-w-0 max-w-full" /></div></div>
      <div class="grid gap-4 md:grid-cols-3"><div class="grid min-w-0 gap-2"><span class="form-label">当这个配置</span><KimaSelect v-model="form.when" label="当这个配置" :items="fields" class="w-full min-w-0 max-w-full" /></div><div class="grid min-w-0 gap-2"><span class="form-label">符合条件</span><KimaSelect v-model="form.operator" label="符合条件" :items="[{value:'eq',label:'等于'},{value:'neq',label:'不等于'},{value:'in',label:'属于列表'},{value:'not_in',label:'不属于列表'},...(source?.kind==='quantity'?[{value:'gte',label:'大于等于'},{value:'lte',label:'小于等于'}]:[])]" class="w-full min-w-0 max-w-full" /></div><div v-if="values.length && !['in','not_in'].includes(form.operator)" class="grid min-w-0 gap-2"><span class="form-label">条件值</span><KimaSelect v-model="form.value" label="条件值" :items="values" class="w-full min-w-0 max-w-full" /></div><div v-else class="grid min-w-0 gap-2"><span class="form-label">条件值</span><KimaTextField v-model="form.value" label="条件值" :placeholder="['in','not_in'].includes(form.operator)?'多个原始值以英文逗号分隔':'整数数量'" required class="w-full min-w-0 max-w-full" /></div></div>
      <div class="grid gap-4 sm:grid-cols-2"><div class="grid min-w-0 gap-2"><span class="form-label">影响这个配置</span><KimaSelect v-model="form.target" label="影响这个配置" :items="options.filter(option=>option.key!==form.when).map(option=>({value:option.key,label:option.name}))" /></div><div class="grid min-w-0 gap-2"><span class="form-label">结果</span><KimaSelect v-model="form.result" label="结果" :items="[{value:'hide',label:'隐藏配置'},{value:'require',label:'设为必选'},...(target?.kind==='quantity'?[{value:'range',label:'限制数量范围'}]:[{value:'allow',label:'限制可选项'}])]" class="w-full min-w-0 max-w-full" /></div></div>
      <div v-if="form.result==='range'" class="grid gap-4 sm:grid-cols-2"><div class="grid min-w-0 gap-2"><span class="form-label">至少数量</span><KimaNumberField v-model="form.minimum" label="至少数量" :min="target?.minimum||0" :max="target?.maximum||100000" class="w-full min-w-0 max-w-full" /></div><div class="grid min-w-0 gap-2"><span class="form-label">至多数量</span><KimaNumberField v-model="form.maximum" label="至多数量" :min="form.minimum" :max="target?.maximum||100000" class="w-full min-w-0 max-w-full" /></div></div>
      <div v-if="form.result==='allow'" class="grid gap-2"><div class="grid min-w-0 gap-2"><span class="form-label">允许的原始值，以英文逗号分隔</span><KimaTextField v-model="form.allowed" label="允许的原始值，以英文逗号分隔" required class="w-full min-w-0 max-w-full" /></div><p class="form-hint">{{ target?.kind==='boolean'?'开关使用true或false。':target?.choices.map(item=>`${item.label} = ${item.value}`).join('；') }}</p></div>
      <KimaButton type="submit" class="w-full sm:w-auto" :loading="busy" :disabled="!options.length">添加联动规则</KimaButton>
    </form>
    <KimaCheckbox v-model="advanced" label="编辑完整规则JSON" />
    <form v-if="advanced" class="grid gap-4" @submit.prevent="saveJSON"><p class="form-hint">支持match=all/any、多条件、多结果、hidden、required、defaultValue与范围交集。条件可引用$period。保存时会校验所有引用和依赖图。</p><div class="grid min-w-0 gap-2"><span class="form-label">完整规则数组</span><KimaTextarea v-model="json" label="完整规则数组" :rows="16" spellcheck="false" /></div><KimaButton type="submit" :loading="busy">校验并保存完整规则</KimaButton></form>
  </KimaCard>
  <KimaCard class="p-5 sm:p-7 grid gap-5">
    <div><h2 class="text-xl font-semibold">客户专属价格</h2><p class="form-hint mt-2">按主账号与周期定价，可限定一份精确配置。命中后替代目录价格，再计算客户组与优惠码减免。币种 {{ currency }}。</p></div>
    <form class="flex flex-col sm:flex-row gap-3" @submit.prevent="findClients"><div class="grid min-w-0 gap-2"><span class="form-label">搜索客户姓名或邮箱</span><KimaTextField v-model="search" label="搜索客户姓名或邮箱" class="flex-1" /></div><KimaButton type="submit" variant="tonal" :loading="busy">查找客户</KimaButton></form>
    <form class="grid gap-4" @submit.prevent="savePrice()">
      <div class="grid gap-4 sm:grid-cols-2"><div class="grid min-w-0 gap-2"><span class="form-label">客户主账号</span><KimaSelect v-model="price.userId" label="客户主账号" searchable :items="clients.map(item=>({value:item.id,label:`${item.name} · ${item.email||item.id.slice(0,8)}`}))" /></div><div class="grid min-w-0 gap-2"><span class="form-label">专属价周期</span><KimaSelect v-model="price.period" label="专属价周期" :items="periods.filter(item=>item.period!=='ontrial').map(item=>({value:item.period,label:item.label}))" /></div><div class="grid min-w-0 gap-2"><span class="form-label">{{ `周期金额（${currency}）` }}</span><KimaTextField v-model="price.price" :label="`周期金额（${currency}）`" inputmode="decimal" required class="w-full min-w-0 max-w-full" /></div><div class="grid min-w-0 gap-2"><span class="form-label">{{ `安装费（${currency}）` }}</span><KimaTextField v-model="price.setup" :label="`安装费（${currency}）`" inputmode="decimal" required class="w-full min-w-0 max-w-full" /></div></div>
      <div class="grid min-w-0 gap-2"><span class="form-label">精确配置JSON，留空适用于此周期的所有配置</span><KimaTextarea v-model="price.configuration" label="精确配置JSON，留空适用于此周期的所有配置" placeholder='例如 {"region":"jp","disk":3}' :rows="3" /></div><div class="grid min-w-0 gap-2"><span class="form-label">有效期截止，留空长期有效</span><KimaTextField v-model="price.expiresAt" label="有效期截止，留空长期有效" type="datetime-local" class="w-full min-w-0 max-w-full" /></div><KimaCheckbox v-model="price.active" label="启用这份专属价" /><KimaButton type="submit" :loading="busy" :disabled="!price.userId">保存客户价格</KimaButton>
    </form>
    <div v-for="item in prices||[]" :key="item.id" class="border rounded-2xl p-4 grid gap-3" style="border-color:var(--kima-color-outline-variant)"><div class="flex flex-wrap justify-between gap-3"><p>{{ item.name }} · {{ item.email||item.userId.slice(0,8) }}</p><KimaChip>{{ item.active?'启用':'停用' }}</KimaChip></div><p>{{ periods.find(period=>period.period===item.period)?.label }} {{ money(item.priceCents,item.currency,item.currencyDecimals) }}，安装费 {{ money(item.setupCents,item.currency,item.currencyDecimals) }}</p><p class="form-hint break-words">{{ item.configuration?JSON.stringify(item.configuration):'适用全部配置' }} · {{ item.expiresAt?date(item.expiresAt):'长期有效' }}</p><KimaButton variant="tonal" :disabled="busy" @click="savePrice(item)">{{ item.active?'停用专属价':'启用专属价' }}</KimaButton></div>
  </KimaCard>
</template>
